// Respuesta para la app: resumen del agente + el GLOBAL actualizado en base64.
// La app muestra `respuesta` como texto y, si viene `archivo`, lo guarda en Storage
// y añade la tarjeta de descarga debajo del texto.
let resumen = $('Agente Modelo 1').first().json.output;
if (Array.isArray(resumen)) {
  resumen = resumen.map((b) => (typeof b === 'string' ? b : b.text || '')).join('');
}
resumen = String(resumen || '').trim() || 'El agente terminó sin devolver resumen.';

let entregar = null;
try {
  entregar = JSON.parse($('M1 - Cerrar').first().json.stdout).entregar;
} catch (e) {}

const item = $input.first();
let archivo = null;
if (entregar && item.binary && item.binary.data) {
  const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
  archivo = { nombre: entregar.nombre, mime: entregar.mime, base64: buf.toString('base64') };
} else if (entregar) {
  resumen += '\n\n(No se pudo adjuntar el GLOBAL: no se encontró el fichero en el servidor.)';
}
return [{ json: { respuesta: resumen, archivo } }];

// Un item por GLOBAL escrito: Normalizar GLOBAL lo lee y Cargar en global_ai lo sube.
// Sin GLOBAL escrito no sale ningún item y no se sincroniza nada.
let cierre = {};
try {
  cierre = JSON.parse($('M1 - Cerrar').first().json.stdout);
} catch (e) {}
return (cierre.globales || []).map((g) => ({ json: { ruta: g.ruta, nombre: g.nombre } }));
